INSERT INTO challenges (id, title, instructions, category, type, difficulty, concepts, spec, legacy)
VALUES
  ('html-estructura-semantica-01', 'Estructura semántica de una página', 'Esta página está hecha solo con <div>. Cámbiala por etiquetas semánticas: una cabecera (<header>) que contenga la navegación (<nav>), un único contenido principal (<main>) y un pie de página (<footer>) después del contenido principal. Mantén los textos.', 'html', 'challenge', 'junior', ARRAY['html-semantico', 'landmarks']::TEXT[], $webwiz_spec${"id":"html-estructura-semantica-01","title":"Estructura semántica de una página","category":"html","difficulty":"junior","concepts":["html-semantico","landmarks"],"instructions":"Esta página está hecha solo con <div>. Cámbiala por etiquetas semánticas: una cabecera (<header>) que contenga la navegación (<nav>), un único contenido principal (<main>) y un pie de página (<footer>) después del contenido principal. Mantén los textos.","files":{"index.html":"<div class=\"cabecera\">\n  <div class=\"menu\">\n    <a href=\"#\">Inicio</a>\n    <a href=\"#\">Blog</a>\n  </div>\n</div>\n<div class=\"contenido\">\n  <h1>Mi blog</h1>\n  <p>Bienvenido a mi blog sobre desarrollo web.</p>\n</div>\n<div class=\"pie\">© 2026 Mi blog</div>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 1rem; }","app.js":""},"editable":["index.html"],"tests":[{"name":"Hay una <nav> dentro de <header>","type":"dom","code":"return !!$('header nav');","message":"La navegación debe ir dentro de un <header>."},{"name":"Hay exactamente un <main> con el título","type":"dom","code":"return $$('main').length === 1 && !!$('main h1');","message":"Usa un único <main> que contenga el <h1>."},{"name":"El <footer> va después del <main>","type":"dom","code":"const m = $('main'), f = $('footer'); if (!m || !f) return 'Falta <main> o <footer>.'; return !!(m.compareDocumentPosition(f) & Node.DOCUMENT_POSITION_FOLLOWING);"},{"name":"Se mantienen los enlaces del menú","type":"dom","code":"return $$('nav a').length >= 2;","message":"Conserva los dos enlaces dentro de la navegación."}],"hints":["Cada <div> tiene una etiqueta semántica equivalente: cabecera → header, menú → nav, contenido → main, pie → footer.","La <nav> no sustituye al <header>: va dentro de él."],"solution":{"index.html":"<header>\n  <nav>\n    <a href=\"#\">Inicio</a>\n    <a href=\"#\">Blog</a>\n  </nav>\n</header>\n<main>\n  <h1>Mi blog</h1>\n  <p>Bienvenido a mi blog sobre desarrollo web.</p>\n</main>\n<footer>© 2026 Mi blog</footer>"}}$webwiz_spec$::jsonb, false),
  ('html-imagen-accesible-01', 'Imagen con texto alternativo y pie de foto', 'La imagen no tiene texto alternativo, así que un lector de pantalla no puede describirla. Añade un atributo alt descriptivo (al menos 10 caracteres) y envuelve la imagen en un <figure> con un <figcaption> que diga «Atardecer en Bilbao».', 'html', 'challenge', 'junior', ARRAY['accesibilidad', 'imagenes']::TEXT[], $webwiz_spec${"id":"html-imagen-accesible-01","title":"Imagen con texto alternativo y pie de foto","category":"html","difficulty":"junior","concepts":["accesibilidad","imagenes"],"instructions":"La imagen no tiene texto alternativo, así que un lector de pantalla no puede describirla. Añade un atributo alt descriptivo (al menos 10 caracteres) y envuelve la imagen en un <figure> con un <figcaption> que diga «Atardecer en Bilbao».","files":{"index.html":"<h1>Galería</h1>\n<img src=\"https://picsum.photos/seed/bilbao/400/250\" width=\"400\" height=\"250\">","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 1rem; }","app.js":""},"editable":["index.html"],"tests":[{"name":"La imagen tiene un alt descriptivo","type":"dom","code":"const img = $('img'); return !!img && (img.getAttribute('alt') || '').trim().length >= 10;","message":"Añade un alt de al menos 10 caracteres que describa la imagen."},{"name":"La imagen está dentro de un <figure>","type":"dom","code":"return !!$('figure img');"},{"name":"El <figcaption> tiene el texto pedido","type":"dom","code":"const c = $('figure figcaption'); return !!c && /atardecer en bilbao/i.test(c.textContent);","message":"Añade <figcaption>Atardecer en Bilbao</figcaption> dentro del <figure>."}],"hints":["El alt describe lo que se ve, como se lo contarías a alguien por teléfono.","Estructura: <figure><img ...><figcaption>...</figcaption></figure>."],"solution":{"index.html":"<h1>Galería</h1>\n<figure>\n  <img src=\"https://picsum.photos/seed/bilbao/400/250\" width=\"400\" height=\"250\" alt=\"Puesta de sol sobre la ría de Bilbao\">\n  <figcaption>Atardecer en Bilbao</figcaption>\n</figure>"}}$webwiz_spec$::jsonb, false),
  ('html-enlaces-01', 'Enlaces internos, externos y de correo', 'Completa los tres enlaces: «Documentación» debe abrir https://developer.mozilla.org en una pestaña nueva de forma segura (target="_blank" con rel="noopener"), «Escríbeme» debe abrir el correo hola@ejemplo.com (mailto:) y «Ir a contacto» debe saltar a la sección con id «contacto».', 'html', 'challenge', 'junior', ARRAY['enlaces', 'seguridad']::TEXT[], $webwiz_spec${"id":"html-enlaces-01","title":"Enlaces internos, externos y de correo","category":"html","difficulty":"junior","concepts":["enlaces","seguridad"],"instructions":"Completa los tres enlaces: «Documentación» debe abrir https://developer.mozilla.org en una pestaña nueva de forma segura (target=\"_blank\" con rel=\"noopener\"), «Escríbeme» debe abrir el correo hola@ejemplo.com (mailto:) y «Ir a contacto» debe saltar a la sección con id «contacto».","files":{"index.html":"<nav>\n  <a>Documentación</a>\n  <a>Escríbeme</a>\n  <a>Ir a contacto</a>\n</nav>\n<main>\n  <section style=\"min-height: 120vh\">Contenido</section>\n  <section>\n    <h2>Contacto</h2>\n  </section>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 1rem; }","app.js":""},"editable":["index.html"],"tests":[{"name":"Enlace externo en pestaña nueva y seguro","type":"dom","code":"const a = $$('a').find(x => /documentaci/i.test(x.textContent)); if (!a) return 'No encuentro el enlace Documentación.'; return a.getAttribute('href') === 'https://developer.mozilla.org' && a.target === '_blank' && /noopener/.test(a.rel);","message":"Necesita href, target=\"_blank\" y rel=\"noopener\"."},{"name":"Enlace de correo con mailto:","type":"dom","code":"const a = $$('a').find(x => /escr/i.test(x.textContent)); return !!a && a.getAttribute('href') === 'mailto:hola@ejemplo.com';"},{"name":"Enlace interno a #contacto","type":"dom","code":"const a = $$('a').find(x => /contacto/i.test(x.textContent)); return !!a && a.getAttribute('href') === '#contacto';"},{"name":"Existe la sección con id contacto","type":"dom","code":"const s = document.getElementById('contacto'); return !!s && /contacto/i.test(s.textContent);","message":"Pon id=\"contacto\" en la sección de contacto."}],"hints":["Un enlace a una parte de la misma página usa # seguido del id del elemento.","Sin rel=\"noopener\", la página abierta podría controlar la tuya mediante window.opener."],"solution":{"index.html":"<nav>\n  <a href=\"https://developer.mozilla.org\" target=\"_blank\" rel=\"noopener noreferrer\">Documentación</a>\n  <a href=\"mailto:hola@ejemplo.com\">Escríbeme</a>\n  <a href=\"#contacto\">Ir a contacto</a>\n</nav>\n<main>\n  <section style=\"min-height: 120vh\">Contenido</section>\n  <section id=\"contacto\">\n    <h2>Contacto</h2>\n  </section>\n</main>"}}$webwiz_spec$::jsonb, false),
  ('html-listas-anidadas-01', 'Menú con submenú usando listas', 'Convierte el menú en una lista no ordenada (<ul>) dentro de la <nav> con tres elementos: Inicio, Cursos y Contacto. «Cursos» debe tener una sublista anidada (dentro de su <li>) con «HTML» y «CSS».', 'html', 'challenge', 'junior', ARRAY['listas', 'html-semantico']::TEXT[], $webwiz_spec${"id":"html-listas-anidadas-01","title":"Menú con submenú usando listas","category":"html","difficulty":"junior","concepts":["listas","html-semantico"],"instructions":"Convierte el menú en una lista no ordenada (<ul>) dentro de la <nav> con tres elementos: Inicio, Cursos y Contacto. «Cursos» debe tener una sublista anidada (dentro de su <li>) con «HTML» y «CSS».","files":{"index.html":"<nav>\n  Inicio\n  Cursos: HTML, CSS\n  Contacto\n</nav>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 1rem; }","app.js":""},"editable":["index.html"],"tests":[{"name":"La nav contiene una <ul> con 3 elementos","type":"dom","code":"const ul = $('nav > ul'); return !!ul && ul.querySelectorAll(':scope > li').length === 3;","message":"Usa <ul> con tres <li> directos dentro de la <nav>."},{"name":"La sublista está dentro del <li> de Cursos","type":"dom","code":"const li = $$('nav > ul > li').find(l => /cursos/i.test(l.firstChild && l.firstChild.textContent || l.textContent)); return !!li && !!li.querySelector(':scope > ul');","message":"La <ul> anidada va dentro del <li> de Cursos, no después."},{"name":"El submenú tiene HTML y CSS","type":"dom","code":"const items = $$('nav > ul > li > ul > li').map(l => l.textContent.trim()); return items.length === 2 && items.includes('HTML') && items.includes('CSS');"}],"hints":["Una lista anidada es una <ul> completa colocada dentro de un <li>.","Estructura: <li>Cursos <ul><li>HTML</li><li>CSS</li></ul></li>."],"solution":{"index.html":"<nav>\n  <ul>\n    <li>Inicio</li>\n    <li>Cursos\n      <ul>\n        <li>HTML</li>\n        <li>CSS</li>\n      </ul>\n    </li>\n    <li>Contacto</li>\n  </ul>\n</nav>"}}$webwiz_spec$::jsonb, false),
  ('html-formulario-labels-01', 'Formulario de contacto accesible', 'Haz accesible el formulario: cada campo debe tener un <label> asociado (con for e id), el email debe ser de tipo email y obligatorio, el mensaje debe ser un <textarea> y el botón debe ser de tipo submit con el texto «Enviar».', 'html', 'challenge', 'semi_senior', ARRAY['formularios', 'accesibilidad']::TEXT[], $webwiz_spec${"id":"html-formulario-labels-01","title":"Formulario de contacto accesible","category":"html","difficulty":"semi_senior","concepts":["formularios","accesibilidad"],"instructions":"Haz accesible el formulario: cada campo debe tener un <label> asociado (con for e id), el email debe ser de tipo email y obligatorio, el mensaje debe ser un <textarea> y el botón debe ser de tipo submit con el texto «Enviar».","files":{"index.html":"<form>\n  Nombre <input name=\"nombre\">\n  Email <input name=\"email\">\n  Mensaje <input name=\"mensaje\">\n  <div class=\"boton\">Enviar</div>\n</form>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 1rem; }\nlabel { display: block; margin-top: .75rem; }","app.js":""},"editable":["index.html"],"tests":[{"name":"Cada campo tiene un <label> asociado","type":"dom","code":"const campos = $$('input, textarea'); if (campos.length < 3) return 'Faltan campos.'; const sin = campos.filter(c => !c.labels || c.labels.length === 0); return sin.length === 0 || ('Sin etiqueta: ' + sin.map(c => c.name).join(', '));"},{"name":"El email es type=email y obligatorio","type":"dom","code":"const e = $('[name=email]'); return !!e && e.type === 'email' && e.required;"},{"name":"El mensaje es un <textarea>","type":"dom","code":"return !!$('textarea[name=mensaje]');"},{"name":"Hay un botón submit «Enviar»","type":"dom","code":"const b = $('form button'); return !!b && b.type === 'submit' && /enviar/i.test(b.textContent);"}],"hints":["<label for=\"email\"> se asocia al campo que tiene id=\"email\".","Un <div> no es un botón: usa <button type=\"submit\">."],"solution":{"index.html":"<form>\n  <label for=\"nombre\">Nombre</label>\n  <input id=\"nombre\" name=\"nombre\">\n  <label for=\"email\">Email</label>\n  <input id=\"email\" name=\"email\" type=\"email\" required>\n  <label for=\"mensaje\">Mensaje</label>\n  <textarea id=\"mensaje\" name=\"mensaje\"></textarea>\n  <button type=\"submit\">Enviar</button>\n</form>"}}$webwiz_spec$::jsonb, false),
  ('html-tabla-accesible-01', 'Tabla de datos accesible', 'Convierte la lista de precios en una tabla de datos: con un <caption> «Planes y precios», una cabecera (<thead>) con celdas <th scope="col"> para «Plan» y «Precio», y un <tbody> con una fila por plan (Básico 5 €, Pro 12 €, Equipo 30 €).', 'html', 'challenge', 'semi_senior', ARRAY['tablas', 'accesibilidad']::TEXT[], $webwiz_spec${"id":"html-tabla-accesible-01","title":"Tabla de datos accesible","category":"html","difficulty":"semi_senior","concepts":["tablas","accesibilidad"],"instructions":"Convierte la lista de precios en una tabla de datos: con un <caption> «Planes y precios», una cabecera (<thead>) con celdas <th scope=\"col\"> para «Plan» y «Precio», y un <tbody> con una fila por plan (Básico 5 €, Pro 12 €, Equipo 30 €).","files":{"index.html":"<div>Planes y precios</div>\n<div>Básico - 5 €</div>\n<div>Pro - 12 €</div>\n<div>Equipo - 30 €</div>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 1rem; }\ntable { border-collapse: collapse; } th, td { border: 1px solid #ccc; padding: .5rem; }","app.js":""},"editable":["index.html"],"tests":[{"name":"La tabla tiene <caption>","type":"dom","code":"const c = $('table caption'); return !!c && /planes y precios/i.test(c.textContent);"},{"name":"Cabecera con <th scope=\"col\">","type":"dom","code":"const ths = $$('table thead th'); return ths.length === 2 && ths.every(t => t.getAttribute('scope') === 'col');","message":"Usa dos <th scope=\"col\"> dentro de <thead>."},{"name":"Tres filas de datos en <tbody>","type":"dom","code":"const rows = $$('table tbody tr'); return rows.length === 3 && rows.every(r => r.children.length === 2);"},{"name":"Los datos son correctos","type":"dom","code":"const t = $('table tbody').textContent.replace(/\\s+/g, ' '); return /Básico/.test(t) && /Pro/.test(t) && /Equipo/.test(t) && /30/.test(t);"}],"hints":["El <caption> va justo después de abrir <table>.","scope=\"col\" indica que la cabecera describe toda la columna."],"solution":{"index.html":"<table>\n  <caption>Planes y precios</caption>\n  <thead>\n    <tr><th scope=\"col\">Plan</th><th scope=\"col\">Precio</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Básico</td><td>5 €</td></tr>\n    <tr><td>Pro</td><td>12 €</td></tr>\n    <tr><td>Equipo</td><td>30 €</td></tr>\n  </tbody>\n</table>"}}$webwiz_spec$::jsonb, false),
  ('html-encabezados-01', 'Jerarquía de encabezados', 'Los encabezados están desordenados: hay dos <h1> y se salta niveles (de h1 a h3). Corrígelos para que haya un único <h1> («Guía de CSS»), las secciones sean <h2> y las subsecciones <h3>, sin saltar ningún nivel. No cambies los textos.', 'html', 'challenge', 'semi_senior', ARRAY['html-semantico', 'accesibilidad', 'seo']::TEXT[], $webwiz_spec${"id":"html-encabezados-01","title":"Jerarquía de encabezados","category":"html","difficulty":"semi_senior","concepts":["html-semantico","accesibilidad","seo"],"instructions":"Los encabezados están desordenados: hay dos <h1> y se salta niveles (de h1 a h3). Corrígelos para que haya un único <h1> («Guía de CSS»), las secciones sean <h2> y las subsecciones <h3>, sin saltar ningún nivel. No cambies los textos.","files":{"index.html":"<h1>Guía de CSS</h1>\n<h1>Selectores</h1>\n<h4>Selectores de clase</h4>\n<h4>Selectores de id</h4>\n<h3>Flexbox</h3>\n<h5>Alinear elementos</h5>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 1rem; }","app.js":""},"editable":["index.html"],"tests":[{"name":"Hay un único <h1> con el título","type":"dom","code":"const h = $$('h1'); return h.length === 1 && /guía de css/i.test(h[0].textContent);"},{"name":"No se salta ningún nivel","type":"dom","code":"let prev = 0; for (const h of $$('h1,h2,h3,h4,h5,h6')) { const n = +h.tagName[1]; if (n > prev + 1) return 'Salto de h' + prev + ' a h' + n + ' en «' + h.textContent + '».'; prev = n; } return true;"},{"name":"Selectores y Flexbox son secciones (<h2>)","type":"dom","code":"const t = $$('h2').map(h => h.textContent.trim()); return t.includes('Selectores') && t.includes('Flexbox');"},{"name":"Se conservan los 6 encabezados","type":"dom","code":"return $$('h1,h2,h3,h4,h5,h6').length === 6;"}],"hints":["Piensa en un índice: título (h1) → capítulos (h2) → apartados (h3).","El tamaño visual se cambia con CSS, nunca eligiendo otro nivel de encabezado."],"solution":{"index.html":"<h1>Guía de CSS</h1>\n<h2>Selectores</h2>\n<h3>Selectores de clase</h3>\n<h3>Selectores de id</h3>\n<h2>Flexbox</h2>\n<h3>Alinear elementos</h3>"}}$webwiz_spec$::jsonb, false),
  ('html-validacion-nativa-01', 'Validación nativa de formularios', 'Usa la validación nativa del navegador, sin JavaScript: la contraseña debe exigir al menos 8 caracteres (minlength) y estar asociada con aria-describedby al texto de ayuda (id «ayuda-pass»). Las opciones de plan deben ser radios del mismo grupo (name="plan"), agrupadas en un <fieldset> con <legend> «Plan», y una de ellas obligatoria.', 'html', 'challenge', 'senior', ARRAY['formularios', 'validacion', 'accesibilidad']::TEXT[], $webwiz_spec${"id":"html-validacion-nativa-01","title":"Validación nativa de formularios","category":"html","difficulty":"senior","concepts":["formularios","validacion","accesibilidad"],"instructions":"Usa la validación nativa del navegador, sin JavaScript: la contraseña debe exigir al menos 8 caracteres (minlength) y estar asociada con aria-describedby al texto de ayuda (id «ayuda-pass»). Las opciones de plan deben ser radios del mismo grupo (name=\"plan\"), agrupadas en un <fieldset> con <legend> «Plan», y una de ellas obligatoria.","files":{"index.html":"<form>\n  <label for=\"pass\">Contraseña</label>\n  <input id=\"pass\" type=\"password\">\n  <p>Mínimo 8 caracteres.</p>\n\n  <p>Plan</p>\n  <label><input type=\"radio\" name=\"plan-gratis\" value=\"gratis\"> Gratis</label>\n  <label><input type=\"radio\" name=\"plan-pro\" value=\"pro\"> Pro</label>\n\n  <button>Crear cuenta</button>\n</form>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 1rem; }","app.js":""},"editable":["index.html"],"tests":[{"name":"La contraseña exige 8 caracteres y es obligatoria","type":"dom","code":"const p = $('#pass'); if (!p) return 'Falta #pass.'; return p.type === 'password' && p.minLength === 8 && p.required;","message":"Usa minlength=\"8\" y required en la contraseña."},{"name":"La ayuda está asociada con aria-describedby","type":"dom","code":"const p = $('#pass'); const id = p && p.getAttribute('aria-describedby'); const ayuda = id && document.getElementById(id); return !!ayuda && ayuda.id === 'ayuda-pass' && /8/.test(ayuda.textContent);"},{"name":"Radios en un fieldset con legend","type":"dom","code":"const f = $('fieldset'); return !!f && /plan/i.test((f.querySelector('legend') || {}).textContent || '') && f.querySelectorAll('input[type=radio]').length === 2;"},{"name":"Los radios son un único grupo obligatorio","type":"dom","code":"const r = $$('input[type=radio]'); if (r.length !== 2) return false; const mismo = r.every(x => x.name === 'plan'); return mismo && r.some(x => x.required) && !$('form').checkValidity();","message":"Mismo name=\"plan\" en ambos y required en al menos uno."}],"hints":["Los radios solo son excluyentes entre sí si comparten el mismo name.","aria-describedby recibe el id del elemento que describe al campo."],"solution":{"index.html":"<form>\n  <label for=\"pass\">Contraseña</label>\n  <input id=\"pass\" type=\"password\" minlength=\"8\" required aria-describedby=\"ayuda-pass\">\n  <p id=\"ayuda-pass\">Mínimo 8 caracteres.</p>\n\n  <fieldset>\n    <legend>Plan</legend>\n    <label><input type=\"radio\" name=\"plan\" value=\"gratis\" required> Gratis</label>\n    <label><input type=\"radio\" name=\"plan\" value=\"pro\"> Pro</label>\n  </fieldset>\n\n  <button>Crear cuenta</button>\n</form>"}}$webwiz_spec$::jsonb, false),
  ('html-dialog-01', 'Ventana modal con <dialog>', 'El JavaScript (solo lectura) abre el elemento con id «modal» llamando a showModal() al pulsar «Abrir». Escribe el HTML de la modal con un <dialog id="modal"> etiquetado por su título (aria-labelledby apuntando a un <h2 id="modal-titulo">) y un botón «Cerrar» dentro de un <form method="dialog">, que cierra la modal sin JavaScript.', 'html', 'challenge', 'senior', ARRAY['dialog', 'accesibilidad']::TEXT[], $webwiz_spec${"id":"html-dialog-01","title":"Ventana modal con <dialog>","category":"html","difficulty":"senior","concepts":["dialog","accesibilidad"],"instructions":"El JavaScript (solo lectura) abre el elemento con id «modal» llamando a showModal() al pulsar «Abrir». Escribe el HTML de la modal con un <dialog id=\"modal\"> etiquetado por su título (aria-labelledby apuntando a un <h2 id=\"modal-titulo\">) y un botón «Cerrar» dentro de un <form method=\"dialog\">, que cierra la modal sin JavaScript.","files":{"index.html":"<button id=\"abrir\">Abrir</button>\n\n<!-- Escribe aquí la modal -->\n","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 1rem; }","app.js":"document.getElementById(\"abrir\").addEventListener(\"click\", () => {\n  document.getElementById(\"modal\").showModal();\n});"},"editable":["index.html"],"tests":[{"name":"Existe un <dialog id=\"modal\">","type":"dom","code":"const d = $('#modal'); return !!d && d.tagName === 'DIALOG';"},{"name":"La modal se nombra con su título","type":"dom","code":"const d = $('#modal'); const t = d && document.getElementById(d.getAttribute('aria-labelledby')); return !!t && t.id === 'modal-titulo' && t.tagName === 'H2';"},{"name":"«Abrir» muestra la modal","type":"dom","code":"click('#abrir'); await wait(20); return $('#modal').open === true;"},{"name":"«Cerrar» la cierra sin JavaScript","type":"dom","code":"const d = $('#modal'); if (!d.open) d.showModal(); const b = d.querySelector('form[method=dialog] button'); if (!b) return 'Falta el botón dentro de <form method=\"dialog\">.'; b.click(); await wait(20); return d.open === false;"}],"hints":["Un <form method=\"dialog\"> dentro de un <dialog> lo cierra al enviarse.","aria-labelledby recibe el id del título de la modal."],"solution":{"index.html":"<button id=\"abrir\">Abrir</button>\n\n<dialog id=\"modal\" aria-labelledby=\"modal-titulo\">\n  <h2 id=\"modal-titulo\">Suscríbete</h2>\n  <p>Recibe un reto nuevo cada semana.</p>\n  <form method=\"dialog\">\n    <button>Cerrar</button>\n  </form>\n</dialog>\n"}}$webwiz_spec$::jsonb, false),
  ('html-skip-link-01', 'Enlace para saltar al contenido', 'Quien navega con teclado tiene que atravesar todo el menú en cada página. Añade como primer elemento enfocable un enlace «Saltar al contenido» (clase «saltar») que lleve al <main> (id «contenido»). Además, da a la <nav> un nombre accesible con aria-label="Principal".', 'html', 'challenge', 'senior', ARRAY['accesibilidad', 'landmarks', 'teclado']::TEXT[], $webwiz_spec${"id":"html-skip-link-01","title":"Enlace para saltar al contenido","category":"html","difficulty":"senior","concepts":["accesibilidad","landmarks","teclado"],"instructions":"Quien navega con teclado tiene que atravesar todo el menú en cada página. Añade como primer elemento enfocable un enlace «Saltar al contenido» (clase «saltar») que lleve al <main> (id «contenido»). Además, da a la <nav> un nombre accesible con aria-label=\"Principal\".","files":{"index.html":"<header>\n  <nav>\n    <a href=\"#\">Inicio</a>\n    <a href=\"#\">Cursos</a>\n    <a href=\"#\">Retos</a>\n    <a href=\"#\">Ranking</a>\n  </nav>\n</header>\n<main>\n  <h1>Bienvenido</h1>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 1rem; }\n.saltar { position: absolute; left: -9999px; }\n.saltar:focus { left: 1rem; top: 1rem; }","app.js":""},"editable":["index.html"],"tests":[{"name":"El primer enlace enfocable es «Saltar al contenido»","type":"dom","code":"const f = $$('a[href], button, input, select, textarea')[0]; return !!f && f.classList.contains('saltar') && /saltar al contenido/i.test(f.textContent);"},{"name":"Apunta al <main id=\"contenido\">","type":"dom","code":"const a = $('.saltar'); const m = $('main'); return !!a && !!m && m.id === 'contenido' && a.getAttribute('href') === '#contenido';"},{"name":"La navegación tiene nombre accesible","type":"dom","code":"return $('nav') && $('nav').getAttribute('aria-label') === 'Principal';"}],"hints":["El enlace debe ir antes que el <header> en el HTML para ser el primero al pulsar Tab.","href=\"#contenido\" salta al elemento con id=\"contenido\"."],"solution":{"index.html":"<a class=\"saltar\" href=\"#contenido\">Saltar al contenido</a>\n<header>\n  <nav aria-label=\"Principal\">\n    <a href=\"#\">Inicio</a>\n    <a href=\"#\">Cursos</a>\n    <a href=\"#\">Retos</a>\n    <a href=\"#\">Ranking</a>\n  </nav>\n</header>\n<main id=\"contenido\">\n  <h1>Bienvenido</h1>\n</main>"}}$webwiz_spec$::jsonb, false),
  ('css-centrar-01', 'Centra la tarjeta', 'Centra .card vertical y horizontalmente dentro de .stage. Puedes usar flexbox o grid: cualquier solución correcta vale.', 'css', 'challenge', 'junior', ARRAY['flexbox', 'grid', 'alineacion']::TEXT[], $webwiz_spec${"id":"css-centrar-01","title":"Centra la tarjeta","category":"css","difficulty":"junior","concepts":["flexbox","grid","alineacion"],"instructions":"Centra .card vertical y horizontalmente dentro de .stage. Puedes usar flexbox o grid: cualquier solución correcta vale.","files":{"index.html":"<div class=\"stage\">\n  <div class=\"card\">Hola 👋</div>\n</div>","styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n.stage {\n  height: 100vh;\n  background: #eef2ff;\n}\n.card {\n  width: 200px;\n  padding: 2rem;\n  background: white;\n  border-radius: 12px;\n}","app.js":""},"editable":["styles.css"],"tests":[{"name":".card centrada en horizontal","type":"dom","code":"const s = rect('.stage'), c = rect('.card'); return near(s.left + s.width / 2, c.left + c.width / 2);"},{"name":".card centrada en vertical","type":"dom","code":"const s = rect('.stage'), c = rect('.card'); return near(s.top + s.height / 2, c.top + c.height / 2);"},{"name":".card conserva su ancho de 200px","type":"dom","code":"return near(rect('.card').width, 200 + 64, 1);","message":"No cambies el tamaño de la tarjeta: centra desde el contenedor."}],"hints":["Piensa en el contenedor, no en la tarjeta.","Con flexbox necesitas dos propiedades de alineación; con grid basta place-items."],"solution":{"styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n.stage {\n  height: 100vh;\n  background: #eef2ff;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n.card {\n  width: 200px;\n  padding: 2rem;\n  background: white;\n  border-radius: 12px;\n}"}}$webwiz_spec$::jsonb, false),
  ('css-boton-tactil-01', 'Botón cómodo para el dedo', 'Haz que .btn sea fácil de pulsar: altura mínima de 44px, padding horizontal de al menos 16px, esquinas redondeadas (border-radius ≥ 8px) y cursor de mano. Además, cuando reciba el foco con teclado (:focus-visible) debe mostrar un contorno (outline) visible.', 'css', 'challenge', 'junior', ARRAY['box-model', 'accesibilidad', 'pseudo-clases']::TEXT[], $webwiz_spec${"id":"css-boton-tactil-01","title":"Botón cómodo para el dedo","category":"css","difficulty":"junior","concepts":["box-model","accesibilidad","pseudo-clases"],"instructions":"Haz que .btn sea fácil de pulsar: altura mínima de 44px, padding horizontal de al menos 16px, esquinas redondeadas (border-radius ≥ 8px) y cursor de mano. Además, cuando reciba el foco con teclado (:focus-visible) debe mostrar un contorno (outline) visible.","files":{"index.html":"<button class=\"btn\">Guardar cambios</button>","styles.css":"body { font-family: system-ui, sans-serif; padding: 2rem; }\n.btn {\n  background: #2f5bd3;\n  color: white;\n  border: none;\n  font-size: 14px;\n}","app.js":""},"editable":["styles.css"],"tests":[{"name":"Altura mínima de 44px","type":"dom","code":"return rect('.btn').height >= 44;"},{"name":"Padding horizontal ≥ 16px y bordes redondeados","type":"dom","code":"const s = style('.btn'); return parseFloat(s.paddingLeft) >= 16 && parseFloat(s.paddingRight) >= 16 && parseFloat(s.borderTopLeftRadius) >= 8;"},{"name":"Cursor de mano","type":"dom","code":"return style('.btn', 'cursor') === 'pointer';"},{"name":"Contorno visible con :focus-visible","type":"dom","code":"for (const sheet of document.styleSheets) for (const r of sheet.cssRules) if (r.selectorText && r.selectorText.includes('.btn:focus-visible') && r.style.outlineStyle && r.style.outlineStyle !== 'none') return true; return 'Añade una regla .btn:focus-visible con outline.';"}],"hints":["44px es el tamaño mínimo de zona táctil que recomiendan las pautas de accesibilidad.","outline: 3px solid ... junto con outline-offset queda mejor que un borde."],"solution":{"styles.css":"body { font-family: system-ui, sans-serif; padding: 2rem; }\n.btn {\n  background: #2f5bd3;\n  color: white;\n  border: none;\n  font-size: 14px;\n  min-height: 44px;\n  padding: 0 20px;\n  border-radius: 10px;\n  cursor: pointer;\n}\n.btn:focus-visible {\n  outline: 3px solid #ffa657;\n  outline-offset: 2px;\n}"}}$webwiz_spec$::jsonb, false),
  ('css-lectura-01', 'Texto cómodo de leer', 'El artículo ocupa toda la pantalla y las líneas están muy pegadas. Limita .articulo a un ancho máximo de 65ch, céntralo horizontalmente con márgenes automáticos y dale a sus párrafos un interlineado (line-height) de al menos 1.5.', 'css', 'challenge', 'junior', ARRAY['tipografia', 'box-model']::TEXT[], $webwiz_spec${"id":"css-lectura-01","title":"Texto cómodo de leer","category":"css","difficulty":"junior","concepts":["tipografia","box-model"],"instructions":"El artículo ocupa toda la pantalla y las líneas están muy pegadas. Limita .articulo a un ancho máximo de 65ch, céntralo horizontalmente con márgenes automáticos y dale a sus párrafos un interlineado (line-height) de al menos 1.5.","files":{"index.html":"<article class=\"articulo\">\n  <h1>Por qué importa la longitud de línea</h1>\n  <p>Las líneas muy largas cansan la vista: al saltar a la línea siguiente cuesta encontrar dónde empieza. Entre 45 y 75 caracteres por línea es lo más cómodo para leer en pantalla.</p>\n  <p>El interlineado también ayuda: con un poco más de aire entre líneas, el ojo no se pierde.</p>\n</article>","styles.css":"body { font-family: Georgia, serif; font-size: 18px; margin: 0; padding: 1rem; }\n.articulo p { line-height: 1.1; }","app.js":""},"editable":["styles.css"],"tests":[{"name":"Ancho máximo de 65ch","type":"dom","code":"const regla = [...document.styleSheets].some(sh => [...sh.cssRules].some(r => r.selectorText === '.articulo' && r.style.maxWidth === '65ch')); return regla && rect('.articulo').width < 900;","message":"Usa max-width: 65ch en .articulo."},{"name":"Centrado horizontalmente","type":"dom","code":"const a = rect('.articulo'); const izq = a.left, der = document.documentElement.clientWidth - a.right; return near(izq, der, 2);"},{"name":"Interlineado de los párrafos ≥ 1.5","type":"dom","code":"const s = style('.articulo p'); return parseFloat(s.lineHeight) / parseFloat(s.fontSize) >= 1.5;"}],"hints":["La unidad ch equivale al ancho del carácter «0» de la fuente.","margin-inline: auto (o margin: 0 auto) centra un bloque con ancho limitado."],"solution":{"styles.css":"body { font-family: Georgia, serif; font-size: 18px; margin: 0; padding: 1rem; }\n.articulo { max-width: 65ch; margin-inline: auto; }\n.articulo p { line-height: 1.6; }"}}$webwiz_spec$::jsonb, false),
  ('css-columnas-flex-01', 'Tres columnas iguales con flexbox', 'Coloca las tres .col de .fila una al lado de la otra, con el mismo ancho y una separación (gap) de 24px entre ellas.', 'css', 'challenge', 'junior', ARRAY['flexbox', 'gap']::TEXT[], $webwiz_spec${"id":"css-columnas-flex-01","title":"Tres columnas iguales con flexbox","category":"css","difficulty":"junior","concepts":["flexbox","gap"],"instructions":"Coloca las tres .col de .fila una al lado de la otra, con el mismo ancho y una separación (gap) de 24px entre ellas.","files":{"index.html":"<section class=\"fila\">\n  <div class=\"col\">Diseño</div>\n  <div class=\"col\">Código</div>\n  <div class=\"col\">Despliegue</div>\n</section>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }\n.col { background: #eef2ff; padding: 1rem; border-radius: 8px; }","app.js":""},"editable":["styles.css"],"tests":[{"name":"Las columnas están en la misma fila","type":"dom","code":"const t = $$('.col').map(c => Math.round(c.getBoundingClientRect().top)); return t.every(x => x === t[0]);"},{"name":"Las tres miden lo mismo","type":"dom","code":"const w = $$('.col').map(c => c.getBoundingClientRect().width); return w.every(x => near(x, w[0], 1)) && w[0] > 100;"},{"name":"Separación de 24px","type":"dom","code":"const c = $$('.col').map(x => x.getBoundingClientRect()); return near(c[1].left - c[0].right, 24, 1) && near(c[2].left - c[1].right, 24, 1);"}],"hints":["display: flex en el contenedor coloca a los hijos en fila.","flex: 1 en los hijos reparte el espacio libre a partes iguales."],"solution":{"styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }\n.fila { display: flex; gap: 24px; }\n.col { flex: 1; background: #eef2ff; padding: 1rem; border-radius: 8px; }"}}$webwiz_spec$::jsonb, false),
  ('css-galeria-grid-01', 'Galería con CSS Grid', 'Organiza las 6 .foto de .galeria en una cuadrícula de 3 columnas iguales con 16px de separación en ambos sentidos. Las fotos deben ocupar todo el ancho de su celda.', 'css', 'challenge', 'semi_senior', ARRAY['grid', 'gap']::TEXT[], $webwiz_spec${"id":"css-galeria-grid-01","title":"Galería con CSS Grid","category":"css","difficulty":"semi_senior","concepts":["grid","gap"],"instructions":"Organiza las 6 .foto de .galeria en una cuadrícula de 3 columnas iguales con 16px de separación en ambos sentidos. Las fotos deben ocupar todo el ancho de su celda.","files":{"index.html":"<div class=\"galeria\">\n  <div class=\"foto\">1</div><div class=\"foto\">2</div><div class=\"foto\">3</div>\n  <div class=\"foto\">4</div><div class=\"foto\">5</div><div class=\"foto\">6</div>\n</div>","styles.css":"body { margin: 0; padding: 20px; font-family: system-ui, sans-serif; }\n.foto { height: 120px; background: #7aa2ff; border-radius: 10px; display: grid; place-items: center; }","app.js":""},"editable":["styles.css"],"tests":[{"name":"Tres fotos por fila (2 filas)","type":"dom","code":"const tops = new Set($$('.foto').map(f => Math.round(f.getBoundingClientRect().top))); return tops.size === 2;"},{"name":"Columnas del mismo ancho","type":"dom","code":"const w = $$('.foto').map(f => f.getBoundingClientRect().width); return w.every(x => near(x, w[0], 1)) && w[0] > 200;"},{"name":"Separación de 16px en filas y columnas","type":"dom","code":"const f = $$('.foto').map(x => x.getBoundingClientRect()); return near(f[1].left - f[0].right, 16, 1) && near(f[3].top - f[0].bottom, 16, 1);"}],"hints":["grid-template-columns: repeat(3, 1fr) crea tres columnas iguales.","gap afecta a filas y columnas a la vez."],"solution":{"styles.css":"body { margin: 0; padding: 20px; font-family: system-ui, sans-serif; }\n.galeria { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }\n.foto { height: 120px; background: #7aa2ff; border-radius: 10px; display: grid; place-items: center; }"}}$webwiz_spec$::jsonb, false),
  ('css-responsive-01', 'Tarjetas responsive con media queries', 'Las tarjetas ya forman 3 columnas en escritorio. Añade una media query para que en pantallas de 600px o menos (max-width: 600px) .tarjetas pase a una sola columna (grid-template-columns: 1fr). No cambies la versión de escritorio.', 'css', 'challenge', 'semi_senior', ARRAY['responsive', 'media-queries', 'grid']::TEXT[], $webwiz_spec${"id":"css-responsive-01","title":"Tarjetas responsive con media queries","category":"css","difficulty":"semi_senior","concepts":["responsive","media-queries","grid"],"instructions":"Las tarjetas ya forman 3 columnas en escritorio. Añade una media query para que en pantallas de 600px o menos (max-width: 600px) .tarjetas pase a una sola columna (grid-template-columns: 1fr). No cambies la versión de escritorio.","files":{"index.html":"<div class=\"tarjetas\">\n  <article>Plan Básico</article>\n  <article>Plan Pro</article>\n  <article>Plan Equipo</article>\n</div>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }\n.tarjetas { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }\narticle { padding: 1.5rem; border: 1px solid #ccc; border-radius: 12px; }","app.js":""},"editable":["styles.css"],"tests":[{"name":"En escritorio siguen siendo 3 columnas","type":"dom","code":"const t = new Set($$('article').map(a => Math.round(a.getBoundingClientRect().top))); return t.size === 1;"},{"name":"Hay una media query de max-width ≤ 600px","type":"dom","code":"const mq = [...document.styleSheets].flatMap(s => [...s.cssRules]).filter(r => r.media); return mq.some(r => { const m = r.conditionText.match(/max-width:\\s*(\\d+)px/); return m && +m[1] <= 600 && +m[1] >= 480; });","message":"Añade @media (max-width: 600px) { ... }."},{"name":"En móvil .tarjetas tiene una columna","type":"dom","code":"const mq = [...document.styleSheets].flatMap(s => [...s.cssRules]).filter(r => r.media && /max-width/.test(r.conditionText)); return mq.some(m => [...m.cssRules].some(r => /\\.tarjetas/.test(r.selectorText) && /^(1fr|minmax\\(0(px)?, 1fr\\))$/.test(r.style.gridTemplateColumns.trim())));","message":"Dentro de la media query, pon grid-template-columns: 1fr en .tarjetas."}],"hints":["Las media queries van después de la regla general para poder sobrescribirla.","Dentro de la media query solo cambia lo que es distinto en móvil."],"solution":{"styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }\n.tarjetas { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }\narticle { padding: 1.5rem; border: 1px solid #ccc; border-radius: 12px; }\n\n@media (max-width: 600px) {\n  .tarjetas { grid-template-columns: 1fr; }\n}"}}$webwiz_spec$::jsonb, false),
  ('css-variables-tema-01', 'Tema con variables CSS', 'El color de marca está repetido. Define en :root la variable --color-marca con el valor #2f5bd3 y úsala (con var()) en el fondo de .boton y en el color de .titulo, de forma que al cambiar la variable cambien ambos.', 'css', 'challenge', 'semi_senior', ARRAY['custom-properties', 'temas']::TEXT[], $webwiz_spec${"id":"css-variables-tema-01","title":"Tema con variables CSS","category":"css","difficulty":"semi_senior","concepts":["custom-properties","temas"],"instructions":"El color de marca está repetido. Define en :root la variable --color-marca con el valor #2f5bd3 y úsala (con var()) en el fondo de .boton y en el color de .titulo, de forma que al cambiar la variable cambien ambos.","files":{"index.html":"<h1 class=\"titulo\">WebWiz</h1>\n<button class=\"boton\">Empezar</button>","styles.css":"body { font-family: system-ui, sans-serif; padding: 2rem; }\n.titulo { color: #2f5bd3; }\n.boton { background: #2f5bd3; color: white; border: 0; padding: .75rem 1.25rem; border-radius: 10px; }","app.js":""},"editable":["styles.css"],"tests":[{"name":"Existe --color-marca en :root","type":"dom","code":"return getComputedStyle(document.documentElement).getPropertyValue('--color-marca').trim().toLowerCase() === '#2f5bd3';"},{"name":"El botón usa la variable","type":"dom","code":"document.documentElement.style.setProperty('--color-marca', 'rgb(1, 2, 3)'); const ok = style('.boton', 'background-color') === 'rgb(1, 2, 3)'; document.documentElement.style.removeProperty('--color-marca'); return ok;"},{"name":"El título usa la variable","type":"dom","code":"document.documentElement.style.setProperty('--color-marca', 'rgb(4, 5, 6)'); const ok = style('.titulo', 'color') === 'rgb(4, 5, 6)'; document.documentElement.style.removeProperty('--color-marca'); return ok;"}],"hints":["Las variables se declaran con dos guiones: --nombre: valor;","Se leen con var(--nombre)."],"solution":{"styles.css":":root { --color-marca: #2f5bd3; }\nbody { font-family: system-ui, sans-serif; padding: 2rem; }\n.titulo { color: var(--color-marca); }\n.boton { background: var(--color-marca); color: white; border: 0; padding: .75rem 1.25rem; border-radius: 10px; }"}}$webwiz_spec$::jsonb, false),
  ('css-sticky-header-01', 'Cabecera fija al hacer scroll', 'Haz que la cabecera se quede pegada arriba al hacer scroll (sin sacarla del flujo: nada de position: fixed) y que quede por encima del contenido, que tiene elementos posicionados con z-index: 1.', 'css', 'challenge', 'senior', ARRAY['position', 'sticky', 'z-index']::TEXT[], $webwiz_spec${"id":"css-sticky-header-01","title":"Cabecera fija al hacer scroll","category":"css","difficulty":"senior","concepts":["position","sticky","z-index"],"instructions":"Haz que la cabecera se quede pegada arriba al hacer scroll (sin sacarla del flujo: nada de position: fixed) y que quede por encima del contenido, que tiene elementos posicionados con z-index: 1.","files":{"index.html":"<header class=\"cabecera\">WebWiz</header>\n<main>\n  <div class=\"tarjeta\">Tarjeta destacada</div>\n  <p style=\"height: 2000px\">Contenido muy largo…</p>\n</main>","styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n.cabecera { background: #161b22; color: white; padding: 1rem; }\n.tarjeta { position: relative; z-index: 1; background: #ffa657; padding: 2rem; }","app.js":""},"editable":["styles.css"],"tests":[{"name":"La cabecera es sticky y no fixed","type":"dom","code":"return style('.cabecera', 'position') === 'sticky';"},{"name":"Sigue arriba tras hacer scroll","type":"dom","code":"window.scrollTo(0, 600); await wait(30); const top = rect('.cabecera').top; window.scrollTo(0, 0); return near(top, 0, 1);"},{"name":"Queda por encima del contenido","type":"dom","code":"window.scrollTo(0, 60); await wait(30); const h = rect('.cabecera'); const el = document.elementFromPoint(h.left + 10, h.top + h.height / 2); window.scrollTo(0, 0); return !!el && !!el.closest('.cabecera');","message":"Al hacer scroll la tarjeta tapa la cabecera: revisa el z-index."}],"hints":["position: sticky necesita un valor de top para saber dónde pegarse.","La tarjeta tiene z-index: 1; la cabecera necesita uno mayor."],"solution":{"styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n.cabecera { background: #161b22; color: white; padding: 1rem; position: sticky; top: 0; z-index: 10; }\n.tarjeta { position: relative; z-index: 1; background: #ffa657; padding: 2rem; }"}}$webwiz_spec$::jsonb, false),
  ('css-grid-areas-01', 'Maquetación con grid-template-areas', 'Maqueta .pagina con grid-template-areas: la cabecera ocupa todo el ancho arriba; debajo, una barra lateral de 240px a la izquierda y el contenido principal ocupando el resto; el pie ocupa todo el ancho abajo. La página debe medir al menos el alto de la ventana.', 'css', 'challenge', 'senior', ARRAY['grid', 'grid-areas', 'layout']::TEXT[], $webwiz_spec${"id":"css-grid-areas-01","title":"Maquetación con grid-template-areas","category":"css","difficulty":"senior","concepts":["grid","grid-areas","layout"],"instructions":"Maqueta .pagina con grid-template-areas: la cabecera ocupa todo el ancho arriba; debajo, una barra lateral de 240px a la izquierda y el contenido principal ocupando el resto; el pie ocupa todo el ancho abajo. La página debe medir al menos el alto de la ventana.","files":{"index.html":"<div class=\"pagina\">\n  <header>Cabecera</header>\n  <aside>Lateral</aside>\n  <main>Contenido</main>\n  <footer>Pie</footer>\n</div>","styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\nheader, aside, main, footer { padding: 1rem; border: 1px solid #ccc; }","app.js":""},"editable":["styles.css"],"tests":[{"name":"Usa grid-template-areas","type":"dom","code":"const s = style('.pagina'); return s.display === 'grid' && s.gridTemplateAreas !== 'none';"},{"name":"Lateral de 240px a la izquierda del contenido","type":"dom","code":"const a = rect('aside'), m = rect('main'); return near(a.width, 240, 1) && a.right <= m.left + 1 && near(a.top, m.top, 1);"},{"name":"Cabecera y pie a todo el ancho","type":"dom","code":"const p = rect('.pagina'), h = rect('header'), f = rect('footer'), m = rect('main'); return near(h.width, p.width, 1) && near(f.width, p.width, 1) && h.bottom <= m.top + 1 && f.top >= m.bottom - 1;"},{"name":"Ocupa al menos el alto de la ventana","type":"dom","code":"return rect('.pagina').height >= window.innerHeight - 1;"}],"hints":["Asigna un nombre a cada parte con grid-area y dibuja el mapa en grid-template-areas.","grid-template-columns: 240px 1fr; grid-template-rows: auto 1fr auto; min-height: 100vh."],"solution":{"styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\nheader, aside, main, footer { padding: 1rem; border: 1px solid #ccc; }\n.pagina {\n  display: grid;\n  min-height: 100vh;\n  grid-template-columns: 240px 1fr;\n  grid-template-rows: auto 1fr auto;\n  grid-template-areas:\n    \"cabecera cabecera\"\n    \"lateral contenido\"\n    \"pie pie\";\n}\nheader { grid-area: cabecera; }\naside { grid-area: lateral; }\nmain { grid-area: contenido; }\nfooter { grid-area: pie; }"}}$webwiz_spec$::jsonb, false),
  ('css-aspect-ratio-01', 'Miniaturas 16:9 sin deformar', 'Las miniaturas de vídeo tienen tamaños distintos y se deforman. Haz que cada .miniatura img ocupe todo el ancho de su tarjeta (300px), tenga proporción 16:9 (aspect-ratio) y recorte la imagen sin deformarla (object-fit: cover).', 'css', 'challenge', 'senior', ARRAY['aspect-ratio', 'object-fit', 'imagenes']::TEXT[], $webwiz_spec${"id":"css-aspect-ratio-01","title":"Miniaturas 16:9 sin deformar","category":"css","difficulty":"senior","concepts":["aspect-ratio","object-fit","imagenes"],"instructions":"Las miniaturas de vídeo tienen tamaños distintos y se deforman. Haz que cada .miniatura img ocupe todo el ancho de su tarjeta (300px), tenga proporción 16:9 (aspect-ratio) y recorte la imagen sin deformarla (object-fit: cover).","files":{"index.html":"<div class=\"lista\">\n  <div class=\"miniatura\"><img src=\"https://picsum.photos/seed/a/400/400\" alt=\"Vídeo 1\"></div>\n  <div class=\"miniatura\"><img src=\"https://picsum.photos/seed/b/800/300\" alt=\"Vídeo 2\"></div>\n</div>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }\n.lista { display: flex; gap: 1rem; }\n.miniatura { width: 300px; }\n.miniatura img { width: 120px; height: 200px; }","app.js":""},"editable":["styles.css"],"tests":[{"name":"Ocupan todo el ancho de la tarjeta","type":"dom","code":"return $$('.miniatura img').every(i => near(i.getBoundingClientRect().width, 300, 1));"},{"name":"Proporción 16:9","type":"dom","code":"return $$('.miniatura img').every(i => { const r = i.getBoundingClientRect(); return near(r.width / r.height, 16 / 9, 0.02); });"},{"name":"Recortan sin deformar","type":"dom","code":"return $$('.miniatura img').every(i => getComputedStyle(i).objectFit === 'cover');"}],"hints":["aspect-ratio: 16 / 9 calcula el alto a partir del ancho, pero solo si el alto es automático.","object-fit: cover rellena la caja recortando lo que sobra."],"solution":{"styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }\n.lista { display: flex; gap: 1rem; }\n.miniatura { width: 300px; }\n.miniatura img { width: 100%; height: auto; aspect-ratio: 16 / 9; object-fit: cover; display: block; }"}}$webwiz_spec$::jsonb, false),
  ('js-sumar-array-01', 'Suma de un array', 'Implementa sumar(numeros), que devuelve la suma de todos los números del array. Con un array vacío debe devolver 0.', 'javascript', 'challenge', 'junior', ARRAY['arrays', 'reduce']::TEXT[], $webwiz_spec${"id":"js-sumar-array-01","title":"Suma de un array","category":"javascript","difficulty":"junior","concepts":["arrays","reduce"],"instructions":"Implementa sumar(numeros), que devuelve la suma de todos los números del array. Con un array vacío debe devolver 0.","files":{"index.html":"<p>Este reto no tiene interfaz: los tests llaman a tus funciones.</p>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }","app.js":"function sumar(numeros) {\n  // Tu código aquí\n}"},"editable":["app.js"],"tests":[{"name":"sumar([1, 2, 3]) devuelve 6","type":"js","code":"return eq(sumar([1, 2, 3]), 6);"},{"name":"sumar([]) devuelve 0","type":"js","code":"return eq(sumar([]), 0);","message":"Con un array vacío la suma es 0, no undefined."},{"name":"Funciona con negativos y decimales","type":"js","code":"return Math.abs(sumar([-1, 2.5, -0.5]) - 1) < 1e-9;"}],"hints":["Recorre el array acumulando el total en una variable que empieza en 0.","reduce((total, n) => total + n, 0): el 0 final es el valor inicial y evita fallar con arrays vacíos."],"solution":{"app.js":"function sumar(numeros) {\n  return numeros.reduce((total, n) => total + n, 0);\n}"}}$webwiz_spec$::jsonb, false),
  ('js-contar-vocales-01', 'Contar vocales (con tildes)', 'Implementa contarVocales(texto), que devuelve cuántas vocales tiene el texto. Debe contar mayúsculas y minúsculas, y también las vocales con tilde o diéresis (á, é, í, ó, ú, ü).', 'javascript', 'challenge', 'junior', ARRAY['strings', 'regex', 'unicode']::TEXT[], $webwiz_spec${"id":"js-contar-vocales-01","title":"Contar vocales (con tildes)","category":"javascript","difficulty":"junior","concepts":["strings","regex","unicode"],"instructions":"Implementa contarVocales(texto), que devuelve cuántas vocales tiene el texto. Debe contar mayúsculas y minúsculas, y también las vocales con tilde o diéresis (á, é, í, ó, ú, ü).","files":{"index.html":"<p>Este reto no tiene interfaz: los tests llaman a tus funciones.</p>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }","app.js":"function contarVocales(texto) {\n  let total = 0;\n  for (const letra of texto) {\n    if (\"aeiou\".includes(letra)) total++;\n  }\n  return total;\n}"},"editable":["app.js"],"tests":[{"name":"Cuenta minúsculas","type":"js","code":"return eq(contarVocales('hola mundo'), 4);"},{"name":"Cuenta mayúsculas","type":"js","code":"return eq(contarVocales('HOLA'), 2);"},{"name":"Cuenta vocales con tilde y diéresis","type":"js","code":"return eq(contarVocales('Murciélago pingüino'), 9);","message":"«Murciélago pingüino» tiene 9 vocales contando é y ü."},{"name":"Texto vacío devuelve 0","type":"js","code":"return eq(contarVocales(''), 0);"}],"hints":["Pasa el texto a minúsculas antes de comparar.","Puedes ampliar la lista de vocales («aeiouáéíóúü») o quitar las tildes con normalize('NFD')."],"solution":{"app.js":"function contarVocales(texto) {\n  let total = 0;\n  for (const letra of texto.toLowerCase()) {\n    if (\"aeiouáéíóúü\".includes(letra)) total++;\n  }\n  return total;\n}"}}$webwiz_spec$::jsonb, false),
  ('js-fizzbuzz-01', 'FizzBuzz en la consola', 'Completa fizzbuzz(n): devuelve «FizzBuzz» si n es múltiplo de 3 y de 5, «Fizz» si solo es múltiplo de 3, «Buzz» si solo es múltiplo de 5 y, si no, el número como texto. El bucle ya imprime del 1 al 15 usando tu función.', 'javascript', 'challenge', 'junior', ARRAY['bucles', 'condicionales', 'modulo']::TEXT[], $webwiz_spec${"id":"js-fizzbuzz-01","title":"FizzBuzz en la consola","category":"javascript","difficulty":"junior","concepts":["bucles","condicionales","modulo"],"instructions":"Completa fizzbuzz(n): devuelve «FizzBuzz» si n es múltiplo de 3 y de 5, «Fizz» si solo es múltiplo de 3, «Buzz» si solo es múltiplo de 5 y, si no, el número como texto. El bucle ya imprime del 1 al 15 usando tu función.","files":{"index.html":"<p>Este reto no tiene interfaz: los tests llaman a tus funciones.</p>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }","app.js":"function fizzbuzz(n) {\n  if (n % 3 === 0) return \"Fizz\";\n  if (n % 5 === 0) return \"Buzz\";\n  return n;\n}\n\nfor (let i = 1; i <= 15; i++) {\n  console.log(fizzbuzz(i));\n}"},"editable":["app.js"],"tests":[{"name":"fizzbuzz(15) devuelve «FizzBuzz»","type":"js","code":"return fizzbuzz(15) === 'FizzBuzz' || ('Devuelve ' + JSON.stringify(fizzbuzz(15)));","message":"Revisa el orden: el caso «múltiplo de ambos» debe comprobarse primero."},{"name":"Devuelve los números como texto","type":"js","code":"return fizzbuzz(7) === '7';","message":"fizzbuzz(7) debe devolver el texto «7», no el número 7."},{"name":"La consola muestra la secuencia del 1 al 15","type":"console","expected":"1\n2\nFizz\n4\nBuzz\nFizz\n7\n8\nFizz\nBuzz\n11\nFizz\n13\n14\nFizzBuzz"}],"hints":["El 15 es múltiplo de 3, así que entra en la primera condición antes de llegar a la de 5.","Comprueba primero n % 15 === 0 y convierte el número con String(n)."],"solution":{"app.js":"function fizzbuzz(n) {\n  if (n % 15 === 0) return \"FizzBuzz\";\n  if (n % 3 === 0) return \"Fizz\";\n  if (n % 5 === 0) return \"Buzz\";\n  return String(n);\n}\n\nfor (let i = 1; i <= 15; i++) {\n  console.log(fizzbuzz(i));\n}"}}$webwiz_spec$::jsonb, false),
  ('js-contador-dom-01', 'Contador con botones', 'Haz funcionar el contador: «+» suma 1 y «−» resta 1 al número de #valor, pero nunca debe bajar de 0.', 'javascript', 'challenge', 'junior', ARRAY['dom', 'eventos']::TEXT[], $webwiz_spec${"id":"js-contador-dom-01","title":"Contador con botones","category":"javascript","difficulty":"junior","concepts":["dom","eventos"],"instructions":"Haz funcionar el contador: «+» suma 1 y «−» resta 1 al número de #valor, pero nunca debe bajar de 0.","files":{"index.html":"<p>Valor: <output id=\"valor\">0</output></p>\n<button id=\"restar\" aria-label=\"Restar\">−</button>\n<button id=\"sumar\" aria-label=\"Sumar\">+</button>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }\nbutton { min-width: 44px; min-height: 44px; font-size: 1.25rem; }","app.js":"const valor = document.getElementById(\"valor\");\nlet cuenta = 0;\n\ndocument.getElementById(\"sumar\").addEventListener(\"click\", () => {\n  cuenta++;\n});\n"},"editable":["app.js"],"tests":[{"name":"«+» incrementa el valor mostrado","type":"dom","code":"click('#sumar'); click('#sumar'); click('#sumar'); return text('#valor') === '3' || ('Muestra ' + text('#valor') + ', esperaba 3.');"},{"name":"«−» decrementa","type":"dom","code":"click('#restar'); return text('#valor') === '2';"},{"name":"Nunca baja de 0","type":"dom","code":"for (let i = 0; i < 5; i++) click('#restar'); return text('#valor') === '0';"}],"hints":["Cambiar la variable no cambia la pantalla: actualiza también valor.textContent.","Math.max(0, cuenta - 1) evita los negativos."],"solution":{"app.js":"const valor = document.getElementById(\"valor\");\nlet cuenta = 0;\n\nconst pintar = () => (valor.textContent = String(cuenta));\n\ndocument.getElementById(\"sumar\").addEventListener(\"click\", () => {\n  cuenta++;\n  pintar();\n});\ndocument.getElementById(\"restar\").addEventListener(\"click\", () => {\n  cuenta = Math.max(0, cuenta - 1);\n  pintar();\n});\n"}}$webwiz_spec$::jsonb, false),
  ('js-filtrar-usuarios-01', 'Filtrar y ordenar usuarios', 'Implementa nombresActivosAdultos(usuarios): devuelve los nombres de los usuarios activos con 18 años o más, ordenados alfabéticamente (según el español: «Álvaro» va antes que «Beatriz»). No debe modificar el array original.', 'javascript', 'challenge', 'semi_senior', ARRAY['filter', 'map', 'sort', 'inmutabilidad']::TEXT[], $webwiz_spec${"id":"js-filtrar-usuarios-01","title":"Filtrar y ordenar usuarios","category":"javascript","difficulty":"semi_senior","concepts":["filter","map","sort","inmutabilidad"],"instructions":"Implementa nombresActivosAdultos(usuarios): devuelve los nombres de los usuarios activos con 18 años o más, ordenados alfabéticamente (según el español: «Álvaro» va antes que «Beatriz»). No debe modificar el array original.","files":{"index.html":"<p>Este reto no tiene interfaz: los tests llaman a tus funciones.</p>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }","app.js":"function nombresActivosAdultos(usuarios) {\n  return usuarios\n    .filter((u) => u.edad > 18)\n    .sort((a, b) => a.nombre > b.nombre ? 1 : -1)\n    .map((u) => u.nombre);\n}"},"editable":["app.js"],"tests":[{"name":"Filtra activos de 18 o más","type":"js","code":"const r = nombresActivosAdultos([{ nombre: 'Ana', edad: 18, activo: true }, { nombre: 'Luis', edad: 30, activo: false }, { nombre: 'Eva', edad: 17, activo: true }]); return eq(r, ['Ana']);"},{"name":"Orden alfabético en español","type":"js","code":"const r = nombresActivosAdultos([{ nombre: 'Beatriz', edad: 20, activo: true }, { nombre: 'Álvaro', edad: 40, activo: true }, { nombre: 'carla', edad: 33, activo: true }]); return eq(r, ['Álvaro', 'Beatriz', 'carla']) || ('Obtenido: ' + JSON.stringify(r));"},{"name":"No modifica el array original","type":"js","code":"const lista = [{ nombre: 'Zoe', edad: 20, activo: true }, { nombre: 'Ana', edad: 20, activo: true }]; nombresActivosAdultos(lista); return lista[0].nombre === 'Zoe';","message":"sort() ordena el array sobre sí mismo: haz una copia antes."}],"hints":["Hay dos condiciones: activo y edad >= 18 (ojo con > frente a >=).","a.localeCompare(b, 'es') compara textos con tildes y mayúsculas correctamente."],"solution":{"app.js":"function nombresActivosAdultos(usuarios) {\n  return usuarios\n    .filter((u) => u.activo && u.edad >= 18)\n    .map((u) => u.nombre)\n    .sort((a, b) => a.localeCompare(b, \"es\"));\n}"}}$webwiz_spec$::jsonb, false),
  ('js-agrupar-por-01', 'Agrupar elementos por una propiedad', 'Implementa agruparPor(lista, clave), que devuelve un objeto cuyas propiedades son los valores de esa clave y cuyos valores son arrays con los elementos correspondientes, en su orden original.', 'javascript', 'challenge', 'semi_senior', ARRAY['reduce', 'objetos']::TEXT[], $webwiz_spec${"id":"js-agrupar-por-01","title":"Agrupar elementos por una propiedad","category":"javascript","difficulty":"semi_senior","concepts":["reduce","objetos"],"instructions":"Implementa agruparPor(lista, clave), que devuelve un objeto cuyas propiedades son los valores de esa clave y cuyos valores son arrays con los elementos correspondientes, en su orden original.","files":{"index.html":"<p>Este reto no tiene interfaz: los tests llaman a tus funciones.</p>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }","app.js":"function agruparPor(lista, clave) {\n  // Tu código aquí\n}"},"editable":["app.js"],"tests":[{"name":"Agrupa por la clave indicada","type":"js","code":"const r = agruparPor([{ t: 'a', n: 1 }, { t: 'b', n: 2 }, { t: 'a', n: 3 }], 't'); return eq(r, { a: [{ t: 'a', n: 1 }, { t: 'a', n: 3 }], b: [{ t: 'b', n: 2 }] });"},{"name":"Lista vacía devuelve {}","type":"js","code":"return eq(agruparPor([], 'x'), {});"},{"name":"No mezcla grupos entre llamadas","type":"js","code":"agruparPor([{ k: 1 }], 'k'); return eq(agruparPor([{ k: 2 }], 'k'), { 2: [{ k: 2 }] });","message":"El objeto resultado debe crearse nuevo en cada llamada."}],"hints":["Empieza con un objeto vacío y, para cada elemento, añádelo al array de su grupo.","Si el grupo aún no existe, créalo: (grupos[valor] ??= []).push(elemento)."],"solution":{"app.js":"function agruparPor(lista, clave) {\n  return lista.reduce((grupos, elemento) => {\n    (grupos[elemento[clave]] ??= []).push(elemento);\n    return grupos;\n  }, {});\n}"}}$webwiz_spec$::jsonb, false),
  ('js-debounce-01', 'Debounce para el buscador', 'Implementa debounce(fn, ms): devuelve una función que, al llamarse varias veces seguidas, solo ejecuta fn una vez, ms milisegundos después de la última llamada y con los argumentos de esa última llamada.', 'javascript', 'challenge', 'semi_senior', ARRAY['closures', 'timers', 'rendimiento']::TEXT[], $webwiz_spec${"id":"js-debounce-01","title":"Debounce para el buscador","category":"javascript","difficulty":"semi_senior","concepts":["closures","timers","rendimiento"],"instructions":"Implementa debounce(fn, ms): devuelve una función que, al llamarse varias veces seguidas, solo ejecuta fn una vez, ms milisegundos después de la última llamada y con los argumentos de esa última llamada.","files":{"index.html":"<p>Este reto no tiene interfaz: los tests llaman a tus funciones.</p>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }","app.js":"function debounce(fn, ms) {\n  return function (...args) {\n    setTimeout(() => fn(...args), ms);\n  };\n}"},"editable":["app.js"],"tests":[{"name":"Varias llamadas seguidas ejecutan fn una sola vez","type":"js","code":"let n = 0; const d = debounce(() => n++, 50); d(); d(); d(); await new Promise(r => setTimeout(r, 120)); return n === 1 || ('fn se ejecutó ' + n + ' veces.');"},{"name":"Usa los argumentos de la última llamada","type":"js","code":"let ultimo; const d = debounce(v => (ultimo = v), 30); d('a'); d('b'); d('c'); await new Promise(r => setTimeout(r, 80)); return ultimo === 'c';"},{"name":"Espera ms desde la última llamada","type":"js","code":"let n = 0; const d = debounce(() => n++, 60); d(); await new Promise(r => setTimeout(r, 40)); d(); await new Promise(r => setTimeout(r, 40)); const antes = n; await new Promise(r => setTimeout(r, 60)); return antes === 0 && n === 1;"}],"hints":["Cada nueva llamada debe cancelar el temporizador anterior.","Guarda el id que devuelve setTimeout en una variable del closure y usa clearTimeout."],"solution":{"app.js":"function debounce(fn, ms) {\n  let temporizador;\n  return function (...args) {\n    clearTimeout(temporizador);\n    temporizador = setTimeout(() => fn.apply(this, args), ms);\n  };\n}"}}$webwiz_spec$::jsonb, false),
  ('js-memoizar-01', 'Memoizar una función costosa', 'Implementa memoizar(fn): devuelve una versión de fn que guarda los resultados por argumentos. Si se llama otra vez con los mismos argumentos, devuelve el resultado guardado sin volver a ejecutar fn. Debe distinguir bien argumentos como 1 y "1", y funcionar con varios argumentos.', 'javascript', 'challenge', 'senior', ARRAY['closures', 'cache', 'map']::TEXT[], $webwiz_spec${"id":"js-memoizar-01","title":"Memoizar una función costosa","category":"javascript","difficulty":"senior","concepts":["closures","cache","map"],"instructions":"Implementa memoizar(fn): devuelve una versión de fn que guarda los resultados por argumentos. Si se llama otra vez con los mismos argumentos, devuelve el resultado guardado sin volver a ejecutar fn. Debe distinguir bien argumentos como 1 y \"1\", y funcionar con varios argumentos.","files":{"index.html":"<p>Este reto no tiene interfaz: los tests llaman a tus funciones.</p>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }","app.js":"function memoizar(fn) {\n  const cache = {};\n  return function (...args) {\n    const clave = args.join(\",\");\n    if (cache[clave]) return cache[clave];\n    return (cache[clave] = fn(...args));\n  };\n}"},"editable":["app.js"],"tests":[{"name":"No repite el cálculo con los mismos argumentos","type":"js","code":"let n = 0; const f = memoizar((a, b) => { n++; return a + b; }); f(2, 3); f(2, 3); return f(2, 3) === 5 && n === 1;"},{"name":"Distingue 1 de \"1\"","type":"js","code":"const f = memoizar(x => typeof x); return f(1) === 'number' && f('1') === 'string';","message":"args.join(',') convierte 1 y '1' en la misma clave."},{"name":"Guarda resultados «falsy» (0, false, '')","type":"js","code":"let n = 0; const f = memoizar(() => { n++; return 0; }); f(); f(); return n === 1;","message":"if (cache[clave]) falla cuando el resultado guardado es 0: comprueba si la clave existe."}],"hints":["Usa una clave que conserve el tipo: JSON.stringify(args).","Comprueba si la clave existe (Map.has o 'clave in cache'), no si el valor es «verdadero»."],"solution":{"app.js":"function memoizar(fn) {\n  const cache = new Map();\n  return function (...args) {\n    const clave = JSON.stringify(args);\n    if (cache.has(clave)) return cache.get(clave);\n    const resultado = fn.apply(this, args);\n    cache.set(clave, resultado);\n    return resultado;\n  };\n}"}}$webwiz_spec$::jsonb, false),
  ('js-reintentar-01', 'Reintentar una petición que falla', 'Implementa reintentar(fn, intentos): llama a la función asíncrona fn y, si su promesa se rechaza, vuelve a intentarlo hasta un total de «intentos» veces. Devuelve el primer resultado correcto; si todos fallan, rechaza con el error del último intento.', 'javascript', 'challenge', 'senior', ARRAY['promesas', 'async-await', 'errores']::TEXT[], $webwiz_spec${"id":"js-reintentar-01","title":"Reintentar una petición que falla","category":"javascript","difficulty":"senior","concepts":["promesas","async-await","errores"],"instructions":"Implementa reintentar(fn, intentos): llama a la función asíncrona fn y, si su promesa se rechaza, vuelve a intentarlo hasta un total de «intentos» veces. Devuelve el primer resultado correcto; si todos fallan, rechaza con el error del último intento.","files":{"index.html":"<p>Este reto no tiene interfaz: los tests llaman a tus funciones.</p>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }","app.js":"async function reintentar(fn, intentos) {\n  for (let i = 0; i < intentos; i++) {\n    try {\n      return fn();\n    } catch (error) {\n      console.log(\"Fallo\", i + 1);\n    }\n  }\n}"},"editable":["app.js"],"tests":[{"name":"Devuelve el resultado si acaba funcionando","type":"js","code":"let n = 0; const fn = async () => { n++; if (n < 3) throw new Error('fallo ' + n); return 'ok'; }; const r = await reintentar(fn, 5); return r === 'ok' && n === 3;"},{"name":"No supera el número de intentos","type":"js","code":"let n = 0; try { await reintentar(async () => { n++; throw new Error('x'); }, 3); } catch (e) {} return n === 3 || ('Se llamó ' + n + ' veces.');"},{"name":"Rechaza con el error del último intento","type":"js","code":"let n = 0; try { await reintentar(async () => { n++; throw new Error('fallo ' + n); }, 2); return 'Debería haber rechazado.'; } catch (e) { return e.message === 'fallo 2'; }"}],"hints":["return fn() devuelve la promesa sin esperarla: el try/catch no ve el rechazo. Usa return await fn().","Guarda el último error en una variable y lánzalo (throw) al terminar el bucle."],"solution":{"app.js":"async function reintentar(fn, intentos) {\n  let ultimoError;\n  for (let i = 0; i < intentos; i++) {\n    try {\n      return await fn();\n    } catch (error) {\n      ultimoError = error;\n    }\n  }\n  throw ultimoError;\n}"}}$webwiz_spec$::jsonb, false),
  ('js-lista-tareas-01', 'Lista de tareas segura con delegación de eventos', 'Completa la lista de tareas: al enviar el formulario se añade un <li> con el texto escrito y un botón «Borrar» (clase «borrar»), y el campo se vacía; los textos vacíos no se añaden. Borrar debe funcionar también en las tareas nuevas con un único listener en la lista (delegación). El texto del usuario nunca debe interpretarse como HTML.', 'javascript', 'challenge', 'senior', ARRAY['dom', 'delegacion-de-eventos', 'xss']::TEXT[], $webwiz_spec${"id":"js-lista-tareas-01","title":"Lista de tareas segura con delegación de eventos","category":"javascript","difficulty":"senior","concepts":["dom","delegacion-de-eventos","xss"],"instructions":"Completa la lista de tareas: al enviar el formulario se añade un <li> con el texto escrito y un botón «Borrar» (clase «borrar»), y el campo se vacía; los textos vacíos no se añaden. Borrar debe funcionar también en las tareas nuevas con un único listener en la lista (delegación). El texto del usuario nunca debe interpretarse como HTML.","files":{"index.html":"<form id=\"form-tarea\">\n  <label for=\"nueva\">Nueva tarea</label>\n  <input id=\"nueva\" autocomplete=\"off\">\n  <button>Añadir</button>\n</form>\n<ul id=\"tareas\"></ul>","styles.css":"body { font-family: system-ui, sans-serif; padding: 1rem; }\nli { display: flex; gap: .5rem; align-items: center; margin: .25rem 0; }","app.js":"const form = document.getElementById(\"form-tarea\");\nconst input = document.getElementById(\"nueva\");\nconst lista = document.getElementById(\"tareas\");\n\nform.addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  lista.innerHTML += \"<li>\" + input.value + \" <button class='borrar'>Borrar</button></li>\";\n});\n"},"editable":["app.js"],"tests":[{"name":"Añade tareas y vacía el campo","type":"dom","code":"const i = $('#nueva'); i.value = 'Comprar pan'; $('#form-tarea').requestSubmit(); if (i.value !== '') return 'El campo no se vacía tras añadir.'; i.value = '   '; $('#form-tarea').requestSubmit(); const items = $$('#tareas li'); if (items.length !== 1) return 'Hay ' + items.length + ' tareas: ¿se añadió la vacía?'; return /Comprar pan/.test(items[0].textContent);"},{"name":"Borrar funciona en tareas nuevas","type":"dom","code":"const i = $('#nueva'); for (const t of ['A', 'B']) { i.value = t; $('#form-tarea').requestSubmit(); } const antes = $$('#tareas li').length; $$('#tareas li .borrar')[0].click(); return $$('#tareas li').length === antes - 1;"},{"name":"El texto no se interpreta como HTML (XSS)","type":"dom","code":"const i = $('#nueva'); i.value = '<img src=x onerror=\"window.hackeado=1\">'; $('#form-tarea').requestSubmit(); await wait(50); const li = $$('#tareas li').pop(); return !window.hackeado && !$('#tareas img') && li.textContent.includes('<img');","message":"Con innerHTML el texto del usuario se ejecuta como HTML: crea los nodos y usa textContent."}],"hints":["Crea el <li> con document.createElement y asigna el texto con textContent: así nunca se interpreta como HTML.","Un solo listener en la <ul> sirve para todos los botones: comprueba si event.target.closest('.borrar') existe."],"solution":{"app.js":"const form = document.getElementById(\"form-tarea\");\nconst input = document.getElementById(\"nueva\");\nconst lista = document.getElementById(\"tareas\");\n\nform.addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const texto = input.value.trim();\n  if (!texto) return;\n\n  const li = document.createElement(\"li\");\n  const span = document.createElement(\"span\");\n  span.textContent = texto;\n  const borrar = document.createElement(\"button\");\n  borrar.type = \"button\";\n  borrar.className = \"borrar\";\n  borrar.textContent = \"Borrar\";\n  li.append(span, borrar);\n  lista.append(li);\n  input.value = \"\";\n});\n\n// Delegación: un único listener para todos los botones, presentes y futuros\nlista.addEventListener(\"click\", (e) => {\n  const boton = e.target.closest(\".borrar\");\n  if (boton) boton.closest(\"li\").remove();\n});\n"}}$webwiz_spec$::jsonb, false)
